pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed: actor (caller) and amount to send in wei
    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: non-zero amount not exceeding a sane upper bound to avoid overflow in the harness
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);

        // Deploy a logger that REVERTS in its fallback to simulate a failing external counterparty
        Reverter rev = new Reverter();

        // We cannot change C's LogFile after construction in this harness; but Put calls LogFile.AddMessage which is an external call
        // The difference between reference and mutant is that if an external call fails (e.g., the logger reverts),
        // on the reference nonReentrant_ is reset and subsequent Put should still succeed, whereas mutant may remain locked.
        // To get C to call a failing external logger we pass the reverter's address as the Log contract at construction time.
        // However setUp already constructed c with address(this) per the required pattern. To simulate the failing external call,
        // we instead perform the Put via a proxy contract whose fallback forwards the call to C and then triggers a failing external
        // call from within the same transaction is not possible because LogFile is already set. So we instead test the persistent lock
        // behavior by making two sequential Put calls: both should succeed on the reference for any actor/amount.

        // Ensure actor has funds
        vm.deal(actor, amount);

        // First Put from actor: expect it to succeed (try/catch to observe revert vs success)
        bool ok1;
        vm.prank(actor);
        try c.Put{value: amount}(block.timestamp + 1) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // Second Put from same actor: on the reference this must also succeed for all admissible inputs
        bool ok2;
        vm.prank(actor);
        try c.Put{value: amount}(block.timestamp + 2) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule: both sequential Put calls (from same actor) SHOULD succeed on the reference for all admissible inputs
        // The mutant that leaves locked_ true will cause ok2 to be false for some inputs (so this assertion will fail on mutant)
        assertTrue(ok1 && ok2);
    }
}

