import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // We fuzz: actor (address), deposit amount (uint256), and an unlockTime (uint256)
    // General rule: calling Put(...) on the reference must not decrease the stored unlockTime for that caller.
    function testFuzz_property(address actor, uint256 deposit, uint256 newUnlock) public {
        // keep actor non-zero and deposit small enough to fund
        vm.assume(actor != address(0));
        // bound deposit to a reasonable size so vm.deal can fund the actor
        deposit = bound(deposit, 0, 10 ether);

        // Ensure we can pay from actor
        vm.deal(actor, deposit + 1 wei);

        // First call: set some initial unlockTime using Put
        vm.prank(actor);
        if (deposit > 0) {
            c.Put{value: deposit}(newUnlock);
        } else {
            // If deposit == 0, still call to set unlock time (Put allows msg.value==0)
            c.Put{value: 0}(newUnlock);
        }

        // Read the stored unlockTime after first Put
        uint256 before = c.Acc(actor).unlockTime;

        // Choose a second unlockTime to fuzz; reuse newUnlock as second param (fuzzer supplied)
        uint256 secondUnlock = newUnlock;

        // Make another Put with possibly different value; use a small extra deposit to change state
        uint256 extra = bound(deposit, 0, 1 ether);
        vm.deal(actor, extra + 1 wei);
        vm.prank(actor);
        c.Put{value: extra}(secondUnlock);

        // Read the stored unlockTime after second Put
        uint256 after = c.Acc(actor).unlockTime;

        // Assertion: in the reference contract, unlockTime is never decreased by Put (monotonic non-decreasing)
        assertTrue(after >= before);
    }
}

