contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit, then attempt collect, then check stored balance decreased by amount.
    // params: depositor address (must be this contract), deposit amount, withdraw amount, unlockTime offset
    function run(uint depositAmt, uint withdrawAmt, uint unlockOffset) public payable {
        // must fund this contract so it can call C.Payable functions and receive refunds
        require(address(this).balance >= depositAmt, "not enough balance for deposit");

        // 1) Put funds into c for this contract's address
        c.Put{value: depositAmt}(block.timestamp + unlockOffset);

        // read stored balance before collect
        (uint beforeBalance) = _getBalance();

        // ensure preconditions similar to contract's checks
        require(beforeBalance >= c.MinSum(), "balance below MinSum");
        require(beforeBalance >= withdrawAmt, "not enough balance for withdraw amount");
        require(block.timestamp > c.Acc(address(this)).unlockTime, "not yet unlocked");

        // 2) Call Collect to withdraw withdrawAmt
        c.Collect(withdrawAmt);

        // 3) read stored balance after collect
        (uint afterBalance) = _getBalance();

        // Assert that stored balance decreased by exactly withdrawAmt
        assert(afterBalance + withdrawAmt == beforeBalance);
    }

    // helper to read Acc mapping's balance via the public getter Acc(address)
    function _getBalance() internal view returns (uint) {
        // c.Acc(address) returns (uint unlockTime, uint balance) but since solidity auto-generated
        // getter returns both, we can capture only balance by skipping first return via a dummy.
        (uint unlockTime, uint balance) = c.Acc(address(this));
        unlockTime; // silence unused
        return balance;
    }

    // Allow this test contract to receive ether for funding deposits
    receive() external payable {}
}

contract InvMutTest {
