    constructor(C _c) { c = _c; }

    // params: amount to withdraw
    function run(uint depositAmount, uint withdrawAmount, uint unlockTime) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // deposit into c so that Acc[msg.sender].balance >= MinSum and >= withdrawAmount and unlockTime < block.timestamp
        // First, call Put by sending Ether via fallback or direct call. Use Put explicitly via fallback is available through payable Put.
        // call Put to set unlock time to a past timestamp to satisfy block.timestamp>acc.unlockTime
        c.Put{value: depositAmount}(unlockTime);

        bool reverted;
        try c.Collect(withdrawAmount) { reverted = false; } catch { reverted = true; }

        // General rule: if depositAmount >= withdrawAmount and depositAmount >= c.MinSum() and unlockTime < block.timestamp
        // then Collect should not revert
        bool cond = (depositAmount >= withdrawAmount) && (depositAmount >= c.MinSum()) && (unlockTime < block.timestamp);
        assert(!cond || !reverted);
