pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to collect and a boolean that controls adversary behavior
    function testFuzz_property(uint256 depositAmount, bool adversaryReverts) public {
        // Keep depositAmount in a reasonable range and >= MinSum so the Collect branch can be taken
        uint256 min = c.MinSum();
        // bound depositAmount to [min, 10 ether]
        depositAmount = bound(depositAmount, min, 10 ether);

        // deploy adversarial recipient which either reverts in receive() or accepts
        Adversary adv = new Adversary(adversaryReverts);

        // fund the adversary so it can send transactions if needed
        vm.deal(address(adv), 1 ether);

        // the test uses adv as msg.sender: we need adv to have previously deposited into c
        // Make adv deposit depositAmount into c by calling Put via fallback (Put is payable and fallback routes to Put(0))
        // Use vm.prank to make the call come from adv
        vm.prank(address(adv));
        // adv must send depositAmount to c
        (bool ok1, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        require(ok1, "deposit failed");

        // ensure adv's recorded balance is >= depositAmount and >= MinSum and unlocked
        // set adv's unlockTime in storage by calling Put with unlockTime in past (0) is already handled as block.timestamp

        // Now attempt to Collect a portion (choose amount <= depositAmount). Let fuzz choose it by reusing depositAmount as upper bound
        uint256 collectAmount = bound(depositAmount / 2, 1 wei, depositAmount);

        // Call Collect from adv and capture whether it reverts. The reference uses low-level call and should not revert even if adv reverts on receive;
        // the mutant using transfer will revert when adv's receive reverts.
        bool completed;
        vm.prank(address(adv));
        try c.Collect(collectAmount) {
            completed = true;
        } catch {
            completed = false;
        }

        // GENERAL ASSERTION: On the reference contract, calling Collect(...) never reverts for any admissible input (caller deposited >= MinSum and sufficient balance).
        // We ensure admissible domain via the deposit above. So assert that the call did NOT revert (reference holds for all admissible inputs),
        // and the mutant (with transfer) will fail for some adversaryReverts=true inputs (fuzzer will find them).
        assertTrue(completed);
    }
}

// Adversarial recipient: when adversaryReverts=true, revert upon receiving Ether; otherwise accept normally
contract Adversary {
    bool public rev;
    constructor(bool _rev) payable {
        rev = _rev;
    }
    receive() external payable {
        if (rev) revert("I refuse funds");
    }
}

